-- Preços: os do seed passam a valer há 20 dias; entram dois reajustes anteriores.
alter table public.tabela_precos disable trigger carimbo;
update public.tabela_precos set vigencia_inicio = ((now() - interval '1728000 seconds') at time zone 'America/Sao_Paulo')::date, created_at = (now() - interval '1728000 seconds'), updated_at = (now() - interval '1728000 seconds'), created_by = '00000000-0000-0000-0000-000000000002';
alter table public.tabela_precos enable trigger carimbo;
alter table public.orcamentos_site disable trigger carimbo;
alter table public.orcamentos_site enable trigger carimbo;
update public.usuarios set created_at = (now() - interval '9266400 seconds');
-- Auditoria com o usuário e a data de cada registro simulado
update public.auditoria set
  usuario_id = coalesce(usuario_id, nullif(coalesce(dados_depois ->> 'created_by', dados_antes ->> 'created_by'), '')::uuid),
  created_at = coalesce((dados_depois ->> 'updated_at')::timestamptz, (dados_antes ->> 'updated_at')::timestamptz, created_at);
